import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.lkcCxhZm.js";const p=JSON.parse('{"title":"System Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md"}'),r={name:"architecture/overview.md"};function i(c,e,l,d,s,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="system-architecture-overview" tabindex="-1">System Architecture Overview <a class="header-anchor" href="#system-architecture-overview" aria-label="Permalink to &quot;System Architecture Overview&quot;">​</a></h1><p>This project is built on a layered architecture designed to bridge the gap between raw source code (text) and application-level data (objects) while maintaining perfect fidelity.</p><h2 id="component-descriptions" tabindex="-1">Component Descriptions <a class="header-anchor" href="#component-descriptions" aria-label="Permalink to &quot;Component Descriptions&quot;">​</a></h2><h3 id="xmlapi" tabindex="-1">XMLAPI <a class="header-anchor" href="#xmlapi" aria-label="Permalink to &quot;XMLAPI&quot;">​</a></h3><p>The public facade and entry point for the library. It provides a clean interface for accessing the source code, the logical model, and the DOM wrapper, while delegating complex synchronization logic to the internal <strong>SyncEngine</strong>.</p><h3 id="syncengine" tabindex="-1">SyncEngine <a class="header-anchor" href="#syncengine" aria-label="Permalink to &quot;SyncEngine&quot;">​</a></h3><p>The core logic unit that orchestrates the Parser, Binder, and History management. It handles:</p><ul><li><strong>Incremental Parsing</strong>: Coordinating with the Parser to update the CST efficiently.</li><li><strong>Synchronization</strong>: Using the Binder to keep the Model in sync with the CST.</li><li><strong>Transaction Management</strong>: Managing undo/redo history.</li></ul><h3 id="dom-interface-document-element-node" tabindex="-1">DOM Interface (Document, Element, Node) <a class="header-anchor" href="#dom-interface-document-element-node" aria-label="Permalink to &quot;DOM Interface (Document, Element, Node)&quot;">​</a></h3><p>A DOM-compatible API layer that wraps the internal Model. It allows developers to interact with the XML as if it were a standard web DOM. When operations (like <code>setAttribute</code>) are performed on these objects, they trigger the Engine to calculate patches for the source code.</p><h3 id="xmlbinder" tabindex="-1">XMLBinder <a class="header-anchor" href="#xmlbinder" aria-label="Permalink to &quot;XMLBinder&quot;">​</a></h3><p>The logic component used by the SyncEngine to handle data synchronization and transformation. It performs:</p><ul><li><strong>Hydration</strong>: Converting CST nodes to Model nodes.</li><li><strong>Reconciliation</strong>: Updating existing model nodes with new CST data to preserve object identity and stable IDs.</li><li><strong>Patch Generation</strong>: Calculating the minimal text change needed to reflect a logical operation in the source XML, respecting existing formatting.</li></ul><h3 id="model-modelelement-modeltext-etc" tabindex="-1">Model (ModelElement, ModelText, etc.) <a class="header-anchor" href="#model-modelelement-modeltext-etc" aria-label="Permalink to &quot;Model (ModelElement, ModelText, etc.)&quot;">​</a></h3><p>The authoritative internal representation of the XML. It sits between the physical CST and the application-level DOM Interface. It manages persistent IDs and maintains the link to the corresponding CST nodes.</p><h3 id="parser-cst" tabindex="-1">Parser &amp; CST <a class="header-anchor" href="#parser-cst" aria-label="Permalink to &quot;Parser &amp; CST&quot;">​</a></h3><p>The <strong>Parser</strong> converts input strings into a <strong>Concrete Syntax Tree (CST)</strong>. The CST captures every character of the source, including whitespace and comments. It supports incremental re-parsing, allowing the system to update only affected branches when the text changes.</p><h3 id="formatter" tabindex="-1">Formatter <a class="header-anchor" href="#formatter" aria-label="Permalink to &quot;Formatter&quot;">​</a></h3><p>Used when generating new XML fragments or performing major structural changes. It can either preserve existing indentation (fidelity mode) or apply new formatting rules (re-format mode).</p><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><ol><li><strong>Source -&gt; Application</strong>: <code>Input String</code> -&gt; <code>SyncEngine</code> -&gt; <code>Parser</code> -&gt; <code>CST</code> -&gt; <code>Binder (Hydrate)</code> -&gt; <code>Model</code> -&gt; <code>DOM Interface</code></li><li><strong>Application -&gt; Source</strong>: <code>DOM Operation</code> -&gt; <code>SyncEngine</code> -&gt; <code>Binder (Patch)</code> -&gt; <code>Text Change</code> -&gt; <code>Update Source</code> -&gt; <code>Incremental Parse</code> -&gt; <code>Model Reconciliation</code></li></ol>',21)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
